# Starter becomes the marketplace package for UMKM (orders, invoices, products, stock, customers); the
# accounting modules are for the larger plans. Pro no longer prints a per-outlet price in its description.
STARTER_TAGLINE = "Untuk UMKM yang ingin merapikan penjualan marketplace."
STARTER_FEATURES = ("Impor pesanan Shopee, Tokopedia & TikTok Shop\nInvoice otomatis dari pesanan marketplace\n"
    "Produk, stok & pemetaan SKU\nStok terpadu dengan 2 toko marketplace\nData pelanggan & pembeli marketplace\n"
    "Bantuan via WhatsApp")
FULL_BOOKS_LINE = "Akuntansi lengkap: pembelian, kas & bank, laporan keuangan, pajak"


def apply(apps, schema_editor):
    Plan = apps.get_model("billing", "Plan")
    Plan.objects.filter(code="free").update(full_books=False, tagline=STARTER_TAGLINE, features=STARTER_FEATURES)
    for plan in Plan.objects.filter(code="pro"):
        lines = [line for line in plan.features.splitlines() if line.strip()]
        lines = ["Multi-outlet" if "399.000" in line or "399000" in line else line for line in lines]
        if FULL_BOOKS_LINE not in lines:
            lines.insert(1 if lines and lines[0].startswith("Semua fitur") else 0, FULL_BOOKS_LINE)
        plan.features = "\n".join(lines)
        plan.save(update_fields=["features"])


